<script setup>
import { ref, computed } from 'vue'
//import { ArrowRight } from 'lucide-vue-next'
import { COMPARISONS } from '@/data/comparisons.js'

const props = defineProps({ data: Object })
const emit = defineEmits(['finish', 'back'])

// Mapeo a íconos Font Awesome, mismo estilo que las tarjetas de sector en Landing.vue
const FA_ICONS = {
  mail: 'fa-solid fa-envelope',
  chat: 'fa-solid fa-comment',
  files: 'fa-solid fa-hard-drive',
  office: 'fa-solid fa-file-lines',
  vpn: 'fa-solid fa-shield',
  intranet: 'fa-solid fa-diagram-project',
  backup: 'fa-solid fa-floppy-disk',
  cost: 'fa-solid fa-dollar-sign',
}

// { mail: false, chat: true, ... }
const selected = ref(Object.fromEntries(COMPARISONS.map(c => [c.key, false])))

const count = computed(() => Object.values(selected.value).filter(Boolean).length)

function toggle(key) {
  selected.value[key] = !selected.value[key]
}

function finish() {
  emit('finish', { ...selected.value })
}

const empNom = computed(() => props.data.empresa || 'Arqueia Tex')
</script>

<template>
  <section id="test">
    <div class="pt-24 md:pt-28 pb-6 md:pb-8 px-4 md:px-8 max-w-3xl mx-auto">

      <!--  <p class="uppercase font-semibold mb-2 text-xs text-teal-500 text-center" style="letter-spacing: 0.16em;">
        {{ $t('proTest.test.eyebrow', { empresa: empNom }) }}
      </p>
      <h2 class="text-2xl md:text-3xl font-extrabold leading-tight mb-2 text-blueGray-700 text-center">
        {{ $t('proTest.test.title') }}
      </h2> -->
      <p class="text-lg mb-5 text-blueGray-500 text-center">
        {{ $t('proTest.test.subtitle', { empresa: empNom }) }}
      </p>

      <div class="grid grid-cols-2" style="gap: 8px;">
        <button v-for="c in COMPARISONS" :key="c.key" @click="toggle(c.key)"
          class="relative text-center rounded-lg px-3 py-4 flex flex-col items-center bg-white transition-colors outline-none focus:outline-none"
          :class="selected[c.key] ? 'shadow-lg border-2' : 'shadow border-2'"
          :style="{ borderColor: selected[c.key] ? 'rgb(94, 207, 190)' : '#e2e8f0' }">

          <span v-if="selected[c.key]"
            class="absolute top-2 right-2 h-5 w-5 rounded-full flex items-center justify-center"
            style="background-color: rgb(13, 92, 82);">
            <i class="fa-solid fa-check text-white" style="font-size: 10px;"></i>
          </span>

          <div
            class="text-white p-2 inline-flex items-center justify-center w-10 h-10 mb-2 shadow-lg rounded-lg bg-teal-500">
            <i :class="FA_ICONS[c.key]" style="font-size: 16px;"></i>
          </div>
          <p class="text-base md:text-base font-medium text-blueGray-700">
            {{ $t(`proTest.comparisons.${c.key}.frase`) }}
          </p>
        </button>
      </div>

      <div class="mt-3 flex items-center justify-center gap-6">
        <button @click="$emit('back')"
          class="inline-flex items-center gap-2 font-semibold text-base px-6 py-3 rounded-lg shadow-lg bg-teal-500 hover:bg-teal-200 text-white transition">
          {{ $t('proTest.test.back') }}
        </button>
        <button @click="finish"
          class="inline-flex items-center gap-2 font-semibold text-base px-6 py-3 rounded-lg shadow-lg bg-teal-500 hover:bg-teal-200 text-white transition">
          {{ $t('proTest.test.cta') }}<span v-if="count > 0"> ({{ count }} {{ $t('proTest.test.marcadas') }})</span>
        </button>
      </div>
    </div>
  </section>
</template>