export const ARS_LICENSE_PER_PC_MONTHLY = 28000

export function formatARS(n) {
  return n.toLocaleString('es-AR', { maximumFractionDigits: 0 })
}

export function slugDomain(empresa) {
  if (!empresa) return 'tuempresa.com'
  return empresa
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '')
    .slice(0, 20) + '.com'
}

export function firstName(full) {
  if (!full) return 'Ricardo'
  return full.trim().split(' ')[0]
}

export function emailHandle(full) {
  if (!full) return 'ricardo.valeva'
  const parts = full.trim().toLowerCase().split(' ').filter(Boolean)
  const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  if (parts.length === 1) return norm(parts[0])
  return `${norm(parts[0])}.${norm(parts[parts.length - 1])}`
}
