<script setup>
import { ref, nextTick } from 'vue'
import FooterComponent from "@/components/Footers/Footer.vue"
import AppHero from '@/components/AppHero.vue'
import IntakeForm from '@/components/IntakeForm.vue'
import TestSection from '@/components/TestSection.vue'
import ResultSection from '@/components/ResultSection.vue'
import Navbar from "@/components/Navbars/AuthNavbar.vue"
import ContactBlock from "@/components/ContactBlock.vue"

// Flujo: null → data → selected
// null     = solo se ve el hero + formulario
// data     = formulario completado, se ve el test
// selected = test completado, se ve el resultado
const data = ref(null)      // { empresa, nombre, rubro, cantidadPCs }
const selected = ref(null)      // { mail: bool, chat: bool, ... }
const started = ref(false)

const formRef = ref(null)
const resultRef = ref(null)

async function scrollToForm() {
  started.value = true
  await nextTick()
  if (!formRef.value) return
  const nav = document.querySelector('nav')
  const navbarHeight = nav ? nav.getBoundingClientRect().height : 64
  const top = formRef.value.getBoundingClientRect().top + window.scrollY - navbarHeight
  window.scrollTo({ top, behavior: 'smooth' })
}

function handleFormSubmit(formData) {
  data.value = formData
}

async function handleFinishTest(sel) {
  selected.value = sel
  await nextTick()
  resultRef.value?.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

function handleBack() {
  started.value = false
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function handleBackToForm() {
  data.value = null
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

</script>



<template>
  <div class="min-h-screen bg-blueGray-200">
    <navbar />

    <AppHero v-if="!started" @scrollToForm="scrollToForm" />

    <!-- Decorador inferior: Curva Suave -->
    <!--         <div class="top-auto bottom-0 left-0 right-0 w-full absolute pointer-events-none overflow-hidden h-70-px"
          style="transform: translateZ(0);">
          <svg class="absolute bottom-0 overflow-hidden" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="none"
            version="1.1" viewBox="0 0 2560 100" x="0" y="0">
            <path fill="rgb(13, 92, 82)" d="M0,0 C1280,100 1280,100 2560,0 L2560,100 L0,100 Z"></path>
          </svg>
        </div> -->


    <main>
      <!-- Formulario -->
      <div ref="formRef">
        <IntakeForm v-if="started && !data" @submit="handleFormSubmit" @back="handleBack" />
      </div>

      <!-- Test -->
      <TestSection v-if="data && !selected" :data="data" @finish="handleFinishTest" @back="handleBackToForm" />

      <!-- Resultado -->
      <div ref="resultRef">
        <ResultSection v-if="data && selected" :data="data" :selected="selected" />
      </div>
    </main>
    <ContactBlock />
    <footer-component />
  </div>
</template>